  async handleShareCommand() {
    try {
      const authResult = spawnSync8("gh", ["auth", "status"], { encoding: "utf-8" });
      if (authResult.status !== 0) {
        this.showError("GitHub CLI is not logged in. Run 'gh auth login' first.");
        return;
      }
    } catch {
      this.showError("GitHub CLI (gh) is not installed. Install it from https://cli.github.com/");
      return;
    }
    const tmpFile = path5.join(os3.tmpdir(), "session.html");
    try {
      await this.agentConnection.exportToHtml(tmpFile);
    } catch (error) {
      this.showError(`Failed to export session: ${error instanceof Error ? error.message : "Unknown error"}`);
      return;
    }
    const loader = new BorderedLoader(this.ui, theme, "Creating gist...");
    this.editorContainer.clear();
    this.editorContainer.addChild(loader);
    this.ui.setFocus(loader);
    this.ui.requestRender();
    const restoreEditor = () => {
      loader.dispose();
      this.editorContainer.clear();
      this.editorContainer.addChild(this.editor);
      this.ui.setFocus(this.editor);
      try {
        fs5.unlinkSync(tmpFile);
      } catch {
      }
    };
    let proc = null;
    loader.onAbort = () => {
      proc?.kill();
      restoreEditor();
      this.showStatus("Share cancelled");
    };
    try {
      const result = await new Promise((resolve19) => {
        proc = spawn8("gh", ["gist", "create", "--public=false", tmpFile]);
        let stdout = "";
        let stderr = "";
        proc.stdout?.on("data", (data) => {
          stdout += data.toString();
        });
        proc.stderr?.on("data", (data) => {
          stderr += data.toString();
        });
        proc.on("close", (code) => resolve19({ stdout, stderr, code }));
      });
      if (loader.signal.aborted)
        return;
      restoreEditor();
      if (result.code !== 0) {
        const errorMsg = result.stderr?.trim() || "Unknown error";
        this.showError(`Failed to create gist: ${errorMsg}`);
        return;
      }
      const gistUrl = result.stdout?.trim();
      const gistId = gistUrl?.split("/").pop();
      if (!gistId) {
        this.showError("Failed to parse gist ID from gh output");
        return;
      }
      const previewUrl = getShareViewerUrl(gistId);
      this.showStatus(`Share URL: ${previewUrl}
Gist: ${gistUrl}`);
    } catch (error) {
      if (!loader.signal.aborted) {
        restoreEditor();
        this.showError(`Failed to create gist: ${error instanceof Error ? error.message : "Unknown error"}`);
      }
    }
  }
